// 30m of lead so the result shows what preceded the alert, not just the breach.
// Azure alerts fire several minutes after the metric moves, so the lead matters more here.
var start = data.in_start || iso(new Date(now.getTime() - 30*60000));
var end   = data.in_end   || iso(now);
