import json, os

def load(name, empty):
    raw = os.environ.get(name, '') or ''
    try:
        return json.loads(raw) if raw.strip() else empty
    except Exception:
        return empty

metrics = load('METRIC_JSON', {})
activity = load('ACTIVITY_JSON', [])
present = load('RUNCMD_JSON', [])
vm_id = os.environ.get('VM_ID', '').lower().rstrip('/')

points = []
for v in metrics.get('value', []) or []:
    for ts in v.get('timeseries', []) or []:
        dims = {m.get('name', {}).get('value'): m.get('value')
                for m in ts.get('metadatavalues', []) or []}
        for p in ts.get('data', []) or []:
            if p.get('average') is None and p.get('maximum') is None:
                continue
            points.append({
                'timestamp': p.get('timeStamp'),
                'average': p.get('average'),
                'maximum': p.get('maximum'),
                'dimensions': dims or None,
                'unit': v.get('unit'),
            })
points.sort(key=lambda x: str(x.get('timestamp') or ''))

# Activity Log for the VM and its child resources (run commands, extensions).
# Azure logs one operation several times - Started, Accepted, Succeeded -
# so collapse to one row per operation, keeping every status seen.
ops = {}
for e in activity if isinstance(activity, list) else []:
    rid = (e.get('resourceId') or '').lower()
    if not rid.startswith(vm_id):
        continue
    op = (e.get('operationName') or {}).get('value') or ''
    if op.lower().startswith('microsoft.authorization/policies/'):
        continue  # policy evaluations: high volume, never the cause
    # the phases of one operation share a correlationId, not an operationId
    key = (e.get('correlationId') or e.get('operationId') or e.get('eventDataId'), op)
    row = ops.setdefault(key, {
        'time': e.get('eventTimestamp'),
        'operation': op,
        'resource': (e.get('resourceId') or '').split('/')[-1],
        'caller': e.get('caller'),
        'statuses': [],
        'error': None,
    })
    if e.get('eventTimestamp') and str(e['eventTimestamp']) < str(row['time']):
        row['time'] = e['eventTimestamp']
    status = (e.get('status') or {}).get('value')
    if status and status not in row['statuses']:
        row['statuses'].append(status)
    props = e.get('properties') or {}
    if status == 'Failed' and not row['error']:
        row['error'] = props.get('statusMessage') or props.get('message')
activity_rows = sorted(ops.values(), key=lambda r: str(r['time'] or ''))
run_ops = [r for r in activity_rows if 'runcommand' in r['operation'].lower()]

# Run Commands still on the VM - the only place the script text survives.
scripts = []
for rc in present if isinstance(present, list) else []:
    src = rc.get('source') or {}
    view = rc.get('instanceView') or {}
    scripts.append({
        'name': rc.get('name'),
        'script': src.get('script') or src.get('commandId') or src.get('scriptUri'),
        'execution_state': view.get('executionState'),
        'start_time': view.get('startTime'),
        'end_time': view.get('endTime'),
        'tags': rc.get('tags'),
    })

print(json.dumps({
    'vm': os.environ.get('VM_NAME', ''),
    'metric_namespace': os.environ.get('METRIC_NAMESPACE', ''),
    'metric_name': os.environ.get('METRIC_NAME', ''),
    'window_start': os.environ.get('WINDOW_START', ''),
    'window_end': os.environ.get('WINDOW_END', ''),
    'datapoint_count': len(points),
    'datapoints': points,
    'run_command_operation_count': len(run_ops),
    'run_command_operations': run_ops,
    'other_activity': [r for r in activity_rows if r not in run_ops],
    'run_commands_present': scripts,
}, default=str))

#!/bin/bash
set -o pipefail
ACTION="${ACTION:-triage}"
hr() { echo; echo "===== $1 ====="; }
case "$ACTION" in
  triage)
    hr "uptime / load"; uptime
    hr "top 10 by CPU"; ps -eo pid,ppid,user,pcpu,pmem,etime,lstart,cmd --sort=-pcpu 2>/dev/null | head -11
    hr "top 10 by memory"; ps -eo pid,ppid,user,pcpu,pmem,etime,cmd --sort=-pmem 2>/dev/null | head -11
    hr "memory"; free -m 2>/dev/null
    hr "disk"; df -hP 2>/dev/null
    hr "boot time"; who -b 2>/dev/null; uptime -s 2>/dev/null ;;
  top_cpu)    hr "top 20 by CPU"; ps -eo pid,ppid,user,pcpu,pmem,etime,lstart,cmd --sort=-pcpu 2>/dev/null | head -21 ;;
  top_memory) hr "top 20 by memory"; ps -eo pid,ppid,user,pcpu,pmem,etime,lstart,cmd --sort=-pmem 2>/dev/null | head -21 ;;
  disk_usage) hr "filesystems"; df -hP 2>/dev/null; hr "largest dirs under /var"; du -xh --max-depth=2 /var 2>/dev/null | sort -rh | head -20 ;;
  memory_usage) hr "free"; free -m 2>/dev/null; hr "meminfo"; head -20 /proc/meminfo 2>/dev/null ;;
  network_connections) hr "listening"; ss -tulpn 2>/dev/null | head -60; hr "established"; ss -tnp state established 2>/dev/null | head -60 ;;
  running_services) hr "running units"; systemctl list-units --type=service --state=running --no-pager 2>/dev/null | head -60 ;;
  failed_services) hr "failed units"; systemctl --failed --no-pager 2>/dev/null ;;
  recent_logins) hr "last logins"; last -a -n 40 2>/dev/null; hr "logged in now"; w 2>/dev/null ;;
  shell_history)
    hr "shell history (most recent 100 per user)"
    for f in /root/.bash_history /home/*/.bash_history; do
      [ -r "$f" ] || continue; echo "--- $f"; tail -100 "$f" 2>/dev/null
    done ;;
  cron_jobs)
    hr "system crontab"; cat /etc/crontab 2>/dev/null
    hr "cron.d"; ls -la /etc/cron.d 2>/dev/null
    hr "per-user crontabs"
    for u in $(cut -d: -f1 /etc/passwd 2>/dev/null); do
      out=$(crontab -l -u "$u" 2>/dev/null); [ -n "$out" ] && { echo "--- $u"; echo "$out"; }
    done
    hr "systemd timers"; systemctl list-timers --all --no-pager 2>/dev/null | head -30 ;;
  recent_syslog) hr "journal (warning+, last 200)"; journalctl -p warning -n 200 --no-pager 2>/dev/null ;;
  process_tree) hr "process tree"; ps -ejH -o pid,ppid,user,pcpu,etime,cmd 2>/dev/null | head -120 ;;
  boot_time) hr "boot"; who -b 2>/dev/null; uptime -s 2>/dev/null; uptime ;;
  package_changes)
    hr "recent package activity"
    if command -v rpm >/dev/null 2>&1; then rpm -qa --last 2>/dev/null | head -40; fi
    if command -v dpkg >/dev/null 2>&1; then grep -h ' install \| upgrade ' /var/log/dpkg.log 2>/dev/null | tail -40; fi ;;
  *) echo "ERROR: unknown host_action '$ACTION'"; exit 2 ;;
esac

